<?php require 'config.php';require_login();$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month))$month=date('Y-m');$first=new DateTimeImmutable($month.'-01');$prev=$first->modify('-1 month')->format('Y-m');$next=$first->modify('+1 month')->format('Y-m');$st=$pdo->prepare('SELECT title,due_date,status FROM tasks WHERE user_id=? AND due_date>=? AND due_date<? ORDER BY due_date');$st->execute([$_SESSION['uid'],$first->format('Y-m-d'),$first->modify('+1 month')->format('Y-m-d')]);$byDay=[];foreach($st->fetchAll() as $task)$byDay[(int)substr($task['due_date'],8,2)][]=$task;$offset=(int)$first->format('N')-1;$days=(int)$first->format('t');require 'header.php';?><div class="calendar-head"><a class="btn secondary" href="?month=<?=$prev?>">← Алдыңғы</a><h1><?=$first->format('Y-m')?> күнтізбесі</h1><a class="btn secondary" href="?month=<?=$next?>">Келесі →</a></div><section class="panel calendar"><div class="weekdays"><?php foreach(['Дс','Сс','Ср','Бс','Жм','Сб','Жс'] as $d): ?><strong><?=$d?></strong><?php endforeach; ?></div><div class="days"><?php for($i=0;$i<$offset;$i++): ?><div class="day empty"></div><?php endfor; ?><?php for($d=1;$d<=$days;$d++): ?><div class="day"><b><?=$d?></b><?php foreach($byDay[$d]??[] as $task): ?><span class="event <?=$task['status']==='done'?'finished':''?>" title="<?=e($task['title'])?>"><?=e($task['title'])?></span><?php endforeach; ?></div><?php endfor; ?></div></section><?php require 'footer.php'; ?>
